#include<iostream>
#include<cstdio>
#include<set>
#include<cstring>
#include<algorithm>
#define INF 0x3f3f3f3f
using namespace std;
const int N=2e5+5;
int n,tot,ans,a[N],b[N];
set<int>st; 
int bs(int x){ 
	set<int>::iterator it=st.lower_bound(x);
	if(it==st.end())return INF;
	return (*it);
}
int main(){
	cin>>n;
	for(int i=1;i<=n;i++)
		scanf("%d",&b[i]);
	sort(b+1,b+n+1,greater<int>());
	int tot=0;a[++tot]=b[1]; 
	for(int i=2,l=1;i<=n;i++){
		if(b[i]==b[l]&&i-l<=1)a[++tot]=b[i];
		else if(b[i]!=b[l])a[++tot]=b[i],l=i;
	}
	for(register int i=1;i<=tot;i++)if(ans<=a[i]+1){
		st.clear(); 
		for(register int j=1;j<=tot;j++){
			if(i==j)continue; 
			int t1=bs(a[j]%a[i]+1-a[i]); 
			if(t1==INF){ 
				int t2=bs(1-a[i]); 
				if(t2!=INF)ans=max(ans,(a[j]%a[i]-t2)%a[i]); 
			}
			else ans=max(ans,(a[j]%a[i]-t1)%a[i]); 
			st.insert(-a[j]%a[i]); 
		}
	}
	cout<<ans<<endl;
	return 0;
}
